import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.Boholvbs.js";const u=JSON.parse('{"title":"Editors & IDEs","description":"Use prioricode inside editors — the VS Code extension, ACP (Agent Client Protocol) for Zed/JetBrains/Neovim, terminal $EDITOR integration, and Zed selection context.","frontmatter":{"title":"Editors & IDEs","description":"Use prioricode inside editors — the VS Code extension, ACP (Agent Client Protocol) for Zed/JetBrains/Neovim, terminal $EDITOR integration, and Zed selection context."},"headers":[],"relativePath":"extending/editors.md","filePath":"extending/editors.md"}'),s={name:"extending/editors.md"};function n(r,e,d,l,h,c){return i(),a("div",null,[...e[0]||(e[0]=[o(`<p>PrioriCode is happiest in a terminal — including the terminal <em>docked in your IDE</em>. But it also speaks two protocols that put it natively inside editors: ACP, and plain <code>$EDITOR</code> handoffs.</p><h2 id="the-terminal-is-the-integration" tabindex="-1">The terminal is the integration <a class="header-anchor" href="#the-terminal-is-the-integration" aria-label="Permalink to &quot;The terminal is the integration&quot;">​</a></h2><p>Run <code>prioricode</code> in VS Code, Cursor, Windsurf, VSCodium, or any IDE&#39;s integrated terminal and two things happen: PrioriCode detects the environment (the <code>TERM_PROGRAM</code>/<code>PRIORICODE_CALLER</code> handshake), and the companion extension can auto-install for tighter wiring.</p><p><strong>The VS Code companion</strong> (published as &quot;PrioriCode&quot; on the VS Code Marketplace and Open VSX) adds:</p><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><code>Cmd/Ctrl+Esc</code></td><td>Open a PrioriCode terminal (focused / new)</td></tr><tr><td><code>Cmd/Ctrl+Option+K</code></td><td>Insert the current file — with a line range, <code>@File#L37-42</code> — into the agent&#39;s prompt</td></tr></tbody></table><p>It&#39;s context-aware: your selection and active file travel with the reference. If auto-install is restricted in your setup (enterprise policy, airgapped), grab <code>prioricode.vsix</code> from the releases and install manually.</p><h2 id="acp-prioricode-as-an-editor-native-agent" tabindex="-1">ACP: PrioriCode as an editor-native agent <a class="header-anchor" href="#acp-prioricode-as-an-editor-native-agent" aria-label="Permalink to &quot;ACP: PrioriCode as an editor-native agent&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acp</span></span></code></pre></div><p>That starts the <strong>Agent Client Protocol</strong> server over stdio (JSON-RPC, newline-delimited) — full agent inside the editor&#39;s own UI: sessions, tool renders, permission prompts, streamed updates, even usage/token counts. It&#39;s not a bridge to the TUI; it&#39;s a second face on the same server (which it spawns locally — network flags and <code>--cwd</code> apply).</p><p>Register it wherever ACP is supported:</p><h4 id="zed" tabindex="-1">Zed <a class="header-anchor" href="#zed" aria-label="Permalink to &quot;Zed&quot;">​</a></h4><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent_servers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;PrioriCode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;custom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prioricode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Open with the <code>agent: new thread</code> action. Zed&#39;s ACP registry may also offer a one-click entry when PrioriCode is listed there — same engine either way.</p><h4 id="jetbrains" tabindex="-1">JetBrains <a class="header-anchor" href="#jetbrains" aria-label="Permalink to &quot;JetBrains&quot;">​</a></h4><p>ACP support lands in recent JetBrains IDEs via an <code>acp.json</code> agent definition pointing at the same <code>prioricode acp</code> command — see the ACP docs for your IDE build.</p><h4 id="neovim" tabindex="-1">Neovim <a class="header-anchor" href="#neovim" aria-label="Permalink to &quot;Neovim&quot;">​</a></h4><p>Plugins that speak ACP — <code>avante.nvim</code>, <code>CodeCompanion.nvim</code> — accept a <code>prioricode</code> agent config the same way; both take the <code>{ command = &quot;prioricode&quot;, args = { &quot;acp&quot; } }</code> shape.</p><p>Feature parity through ACP: built-in tools, custom tools/commands, MCP servers, <code>AGENTS.md</code> rules, formatters/LSP, and agents-with-permissions all apply — it&#39;s the same engine. One known gap: <code>/undo</code>/<code>/redo</code> (transcript time travel) isn&#39;t surfaced through the protocol.</p><h2 id="editor-properly" tabindex="-1"><code>$EDITOR</code>, properly <a class="header-anchor" href="#editor-properly" aria-label="Permalink to &quot;\`$EDITOR\`, properly&quot;">​</a></h2><ul><li><strong><code>/editor</code></strong> (or <code>&lt;leader&gt;e</code>) opens your <code>$VISUAL</code>/<code>$EDITOR</code> to compose the next prompt — multi-prompt-in-one-file territory. <code>EDITOR=&quot;code --wait&quot;</code> works exactly like you&#39;d expect.</li><li><strong><code>/export</code></strong> pipes a transcript through the editor too, with toggles for thinking blocks, tool details, and metadata before the file lands.</li><li><strong>Zed selection context:</strong> run the TUI with Zed open and it can pick up your current selection as attached context on submit (<code>clear</code> it via the editor-context command if it&#39;s not what you meant).</li></ul><h2 id="which-do-i-want" tabindex="-1">Which do I want? <a class="header-anchor" href="#which-do-i-want" aria-label="Permalink to &quot;Which do I want?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Use</th></tr></thead><tbody><tr><td>Live in a terminal already; want zero protocol</td><td>Integrated terminal + the VS Code extension</td></tr><tr><td>Want the agent inside the editor&#39;s UI chrome</td><td>ACP (<code>prioricode acp</code>)</td></tr><tr><td>Just need to compose a long prompt</td><td><code>/editor</code> / <code>&lt;leader&gt;e</code></td></tr><tr><td>Neovim without ACP plugins</td><td>Terminal is genuinely the integration</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../using/tui.html">Terminal UI</a> — The full keyboard-driven experience ACP competes with. <ul><li><a href="./../platforms/server.html">Server &amp; remote</a> — ACP&#39;s sibling: the same server over HTTP.</li><li><a href="./../reference/keybinds.html">Keybinds</a> — The terminal-side chord table — every TUI default, rebindable.</li></ul></li></ul>`,24)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
